//! Original whole-archive keyword override judgement over one evaluated walker.
//! SpacemanDMM 0290db5c752fa292f9824521515b603a2afd11dc (GPL-3.0).
//! State is an operation-local policy fold, never a semantic cache or AST copy.
use crate::{checker_call_facts::CallableFact,checker_effects::{EffectReportWork,ExecutionAdmission,EffectTarget},policy_body_demand::PolicyFailure};
use dm_ir::{PackedU128,Resolver,SymbolId,ProcedureIdentity};
use dm_tree::{SemanticTree,MemberKind,frontend::BodyArchive};
use dm_syntax::{Expr,ExprKind,Span};
use std::{collections::{BTreeMap,BTreeSet},fmt::{self,Write},io,mem::size_of,sync::Arc};
pub const REGISTRATION_TAG: &str = "override_missing_keyword_arg";
pub const DEFAULT_SEVERITY: crate::check_policy::DiagnosticSeverity =
    crate::check_policy::DiagnosticSeverity::Error;

#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum Point{Source(Span),Builtin}
pub struct Note{pub point:Point,pub message:String}
pub struct Finding{pub point:Point,pub message:String,pub notes:Vec<Note>}
pub struct Findings<'a>{archive:&'a BodyArchive,rows:Vec<Finding>}
impl Findings<'_>{pub fn rows(&self)->&[Finding]{&self.rows}pub fn belongs_to(&self,archive:&BodyArchive)->bool{std::ptr::eq(self.archive,archive)}pub fn point(&self,point:Point)->Result<PointProjection<'_>,String>{Ok(match point{Point::Source(at)=>PointProjection::Source(self.archive.borrowed_source_note_point(at.start)?),Point::Builtin=>PointProjection::Builtin})}}
pub struct LegacyNote<'a>{source:PointProjection<'a>,current:PointProjection<'a>,message:&'a str}
impl fmt::Display for LegacyNote<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{let source=self.source.coordinates();let current=self.current.coordinates();if source==current{f.write_str(self.message)}else if source.0==current.0{write!(f,"{}:{}: {}",source.1,source.2,self.message)}else{write!(f,"{}:{}:{}: {}",source.0.display(),source.1,source.2,self.message)}}}
impl Findings<'_>{pub fn legacy_note<'a>(&'a self,primary:Point,note:&'a Note)->Result<LegacyNote<'a>,String>{Ok(LegacyNote{source:self.point(note.point)?,current:self.point(primary)?,message:&note.message})}}
pub enum PointProjection<'a>{Source(dm_tree::frontend::BorrowedSourceNoteOrigin<'a>),Builtin}
impl PointProjection<'_>{pub fn coordinates(&self)->(&std::path::Path,usize,usize){match self{Self::Source(point)=>point.reported_coordinates(),Self::Builtin=>(std::path::Path::new("(builtins)"),1,1)}}}
struct CalledAt{at:Span,others:u32}
struct BadOverride<'a>{missing:Vec<&'a str>,at:Point}
struct Usage<'a>{definition:Point,called_at:BTreeMap<&'a str,CalledAt>,bad:BTreeMap<&'a str,BadOverride<'a>>}
#[derive(Clone,Copy)]struct Group<'a>{owner:&'a str,name:&'a str}
impl PartialEq for Group<'_>{fn eq(&self,other:&Self)->bool{self.cmp(other)==std::cmp::Ordering::Equal}}impl Eq for Group<'_>{}
impl Ord for Group<'_>{fn cmp(&self,other:&Self)->std::cmp::Ordering{self.owner.bytes().chain(b"/proc/".iter().copied()).chain(self.name.bytes()).cmp(other.owner.bytes().chain(b"/proc/".iter().copied()).chain(other.name.bytes()))}}
impl PartialOrd for Group<'_>{fn partial_cmp(&self,other:&Self)->Option<std::cmp::Ordering>{Some(self.cmp(other))}}
impl fmt::Display for Group<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{}/proc/{}",self.owner,self.name)}}
struct Fold<'a,'w,W>{archive:&'a BodyArchive,profile:PackedU128,work:&'w mut W,poll:&'w dyn Fn()->io::Result<()>,used:BTreeMap<Group<'a>,Usage<'a>>,names:BTreeSet<&'a str>}
fn oom()->PolicyFailure{PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"keyword fold allocation geometry overflow"))}
fn reserve<W:EffectReportWork>(work:&mut W,bytes:usize)->Result<(),PolicyFailure>{work.reserve(bytes).map_err(PolicyFailure::Operational)}
fn map_entry<T,W:EffectReportWork>(work:&mut W)->Result<(),PolicyFailure>{reserve(work,size_of::<T>().checked_mul(16).and_then(|n|n.checked_add(2048)).ok_or_else(oom)?)}
fn vector<T,W:EffectReportWork>(work:&mut W,count:usize)->Result<Vec<T>,PolicyFailure>{let bound=count.checked_mul(4).ok_or_else(oom)?;reserve(work,bound.checked_mul(size_of::<T>()).and_then(|n|n.checked_add(size_of::<Vec<T>>()+64)).ok_or_else(oom)?)?;let mut out=Vec::new();out.try_reserve_exact(count).map_err(|e|PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,e)))?;if out.capacity()>bound{return Err(oom())}Ok(out)}
struct Count(usize);impl Write for Count{fn write_str(&mut self,s:&str)->fmt::Result{self.0=self.0.checked_add(s.len()).ok_or(fmt::Error)?;Ok(())}}
struct Fixed<'a>(&'a mut String);impl Write for Fixed<'_>{fn write_str(&mut self,s:&str)->fmt::Result{if s.len()>self.0.capacity()-self.0.len(){return Err(fmt::Error)}self.0.push_str(s);Ok(())}}
fn text<W:EffectReportWork>(work:&mut W,args:fmt::Arguments<'_>)->Result<String,PolicyFailure>{let mut count=Count(0);count.write_fmt(args).map_err(|_|oom())?;let bound=count.0.checked_mul(4).ok_or_else(oom)?;reserve(work,bound.checked_add(size_of::<String>()+64).ok_or_else(oom)?)?;let mut out=String::new();out.try_reserve_exact(count.0).map_err(|e|PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,e)))?;if out.capacity()>bound{return Err(oom())}Fixed(&mut out).write_fmt(args).map_err(|_|oom())?;Ok(out)}
struct Equal<'a>{expected:&'a [u8],at:usize,equal:bool}impl Write for Equal<'_>{fn write_str(&mut self,s:&str)->fmt::Result{let end=self.at.checked_add(s.len()).ok_or(fmt::Error)?;self.equal&=self.expected.get(self.at..end)==Some(s.as_bytes());self.at=end;Ok(())}}
fn key_matches(key:&Expr,name:&str)->Result<bool,PolicyFailure>{match &key.kind{ExprKind::Ident(actual)=>Ok(actual==name),ExprKind::Literal(literal)=>{let mut sink=Equal{expected:name.as_bytes(),at:0,equal:true};let static_text=literal.write_pinned_static_text(&mut sink).map_err(|e|format!("keyword original text: {e:?}"))?;Ok(static_text&&sink.equal&&sink.at==name.len())},_=>Ok(false)}}
impl<'a,W:EffectReportWork> Fold<'a, '_,W>{
 fn spelling(&self,symbol:SymbolId,builtin:bool)->Result<&'a str,PolicyFailure>{if builtin{let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("keyword catalog spelling: {e:?}"))?;if catalog.profile!=self.profile{return Err("keyword spelling profile differs".into())}catalog.spelling(symbol).ok_or_else(||"keyword fixed catalog spelling absent".into())}else{self.archive.tree().symbols().text(symbol).ok_or_else(||"keyword source spelling absent".into())}}
 fn member(&self,id:ProcedureIdentity)->Result<dm_tree::MemberId,PolicyFailure>{let tree=self.archive.tree();let owner=tree.lookup_type(id.owner).ok_or("keyword original owner absent")?;let kind=if id.verb{MemberKind::Verb}else{MemberKind::Proc};let mut current=tree.resolve(owner,id.name,kind);let mut remaining=self.archive.callables().members().len();while let Some(member)=current{(self.poll)().map_err(PolicyFailure::Operational)?;remaining=remaining.checked_sub(1).ok_or("keyword original member chain cycles")?;let node=tree.member(member).ok_or("keyword original member absent")?;if node.owner!=owner{break}if self.archive.callables().identity_for_member(member)==Some(id){return Ok(member)}current=node.previous;}Err("keyword identity has no exact original member".into())}

 fn point(&self,target:EffectTarget)->Result<Point,PolicyFailure>{match target{EffectTarget::Builtin(_)=>Ok(Point::Builtin),EffectTarget::Source(id)=>{let member=self.member(id)?;Ok(Point::Source(self.archive.callable_header_source().reported_span(member)?))}}}
 fn parent(&self,target:EffectTarget,resolver:&(impl Resolver+?Sized))->Result<Option<EffectTarget>,PolicyFailure>{(self.poll)().map_err(PolicyFailure::Operational)?;Ok(match target{EffectTarget::Source(id)=>crate::checker_effects::source_parent_using(self.archive,resolver,self.profile,self.member(id)?,id,&mut||(self.poll)().map_err(PolicyFailure::Operational))?,EffectTarget::Builtin(_)=>crate::checker_effects::original_target_parent_using(self.archive,self.profile,resolver,target,&mut||(self.poll)().map_err(PolicyFailure::Operational))?})}
 fn label(&self,target:EffectTarget)->Result<Option<Group<'a>>,PolicyFailure>{
  if let Some(group)=crate::checker_original_group::Group::for_target_using(self.archive.tree(),self.profile,target,&mut||(self.poll)().map_err(PolicyFailure::Operational))?{let(_,count)=group.coordinates_using(target,&mut||(self.poll)().map_err(PolicyFailure::Operational))?;if count>1{return Ok(None)}return Err("mixed original group has no combined values".into())}
 let tree=self.archive.tree();let builtin=matches!(target,EffectTarget::Builtin(_));let(owner,name,count)=match target{EffectTarget::Source(id)=>{let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("keyword catalog: {e:?}"))?;if catalog.declarations.iter().any(|r|r.owner==id.owner&&r.name==id.name&&matches!(r.kind,MemberKind::Proc|MemberKind::Verb)){return Err("keyword source/builtin value chronology is not issued".into())}let owner=tree.lookup_type(id.owner).ok_or("keyword source owner absent")?;let kind=if id.verb{MemberKind::Verb}else{MemberKind::Proc};let other=if id.verb{MemberKind::Proc}else{MemberKind::Verb};if tree.resolve(owner,id.name,other).is_some_and(|member|tree.member(member).is_some_and(|row|row.owner==owner)&&self.archive.callables().identity_for_member(member).is_some()){return Err("keyword mixed proc/verb chronology is not issued".into())}let mut current=tree.resolve(owner,id.name,kind);let mut remaining=self.archive.callables().members().len();let mut count=0usize;while let Some(member)=current{(self.poll)().map_err(PolicyFailure::Operational)?;remaining=remaining.checked_sub(1).ok_or("keyword original group cycles")?;let row=tree.member(member).ok_or("keyword group member absent")?;if row.owner!=owner{break}if row.name!=id.name||row.kind!=kind||self.archive.callables().identity_for_member(member).is_none(){return Err("keyword original callable value is unissued".into())}count=count.checked_add(1).ok_or_else(oom)?;current=row.previous;}(id.owner,id.name,count)},EffectTarget::Builtin(id)=>{let(owner,name)=tree.with_checker_builtin_procedure(id,|row|(row.owner,row.name)).map_err(|e|format!("keyword builtin label: {e:?}"))?;let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("keyword catalog: {e:?}"))?;let count=catalog.declarations.iter().filter(|r|r.owner==owner&&r.name==name&&matches!(r.kind,MemberKind::Proc|MemberKind::Verb)).count();(owner,name,count)}};
 // ProcRef::Display adds [idx/count] for every multi-value group. Used
 // receiver keys are deliberately unsuffixed in the original judgement.
 if count>1{return Ok(None)}if count==0{return Err("keyword actual callable group is empty".into())}let owner=self.spelling(owner,builtin)?;let name=self.spelling(name,builtin)?;Ok(Some(Group{owner:if owner=="/"{""}else{owner},name}))
 }
 fn interested(&self,name:SymbolId,builtin:bool)->Result<bool,PolicyFailure>{let name=self.spelling(name,builtin)?;Ok(self.names.contains(name))}
 fn check_override(&mut self,id:ProcedureIdentity,resolver:&(impl Resolver+?Sized))->Result<(),PolicyFailure>{
  if !self.interested(id.name,false)?{return Ok(())}let tree=self.archive.tree();let member=self.member(id)?;let metadata=&tree.member(member).ok_or("keyword override declaration absent")?.metadata;let at=Point::Source(self.archive.callable_header_source().reported_span(member)?);self.check_parts(EffectTarget::Source(id),metadata,id.owner,at,resolver)
 }
 fn check_builtin(&mut self,row:&dm_tree::checker_builtins::CheckerBuiltinDeclaration,resolver:&(impl Resolver+?Sized))->Result<(),PolicyFailure>{
  if !self.interested(row.name,true)?{return Ok(())}let tree=self.archive.tree();
  let id=tree.checker_builtin_procedure_identity(self.profile,row.owner,row.name,row.kind==MemberKind::Verb,&row.metadata).map_err(|e|format!("keyword original builtin identity: {e:?}"))?;self.check_parts(EffectTarget::Builtin(id),&row.metadata,row.owner,Point::Builtin,resolver)
 }
 fn check_parts(&mut self,target:EffectTarget,metadata:&dm_ir::DeclarationMeaning,owner:SymbolId,at:Point,resolver:&(impl Resolver+?Sized))->Result<(),PolicyFailure>{
  let tree=self.archive.tree();let parameters=&metadata.procedure.as_ref().ok_or("keyword override signature absent")?.signature.parameters;let builtin=matches!(target,EffectTarget::Builtin(_));let owner=self.spelling(owner,builtin)?;for parameter in parameters.iter(){self.spelling(parameter.name,builtin)?;}
  let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("keyword catalog: {e:?}"))?;let mut remaining=self.archive.callables().members().len().checked_add(catalog.declarations.len()).ok_or_else(oom)?;let mut next=self.parent(target,resolver)?;
  while let Some(current)=next{(self.poll)().map_err(PolicyFailure::Operational)?;remaining=remaining.checked_sub(1).ok_or("keyword predecessor cycle")?;
   if let Some(label)=self.label(current)?{if let Some(usage)=self.used.get_mut(&label){let missing_count=usage.called_at.keys().filter(|&&name|!parameters.iter().any(|p|p.name==SymbolId::of(name))).count();if missing_count>0{let mut missing=vector(self.work,missing_count)?;for name in usage.called_at.keys(){if !parameters.iter().any(|p|p.name==SymbolId::of(*name)){missing.push(*name)}}
    map_entry::<(&str,BadOverride<'_>),_>(self.work)?;usage.bad.insert(if owner=="/"{""}else{owner},BadOverride{missing,at});
    // Retained missing-name coordinates and replacement overlap remain funded
    // conservatively until this operation-local fold physically drops.
   }
   }
   }next=self.parent(current,resolver)?;
  }Ok(())
 }
 fn finish(&mut self)->Result<Vec<Finding>,PolicyFailure>{let mut rows=vector(self.work,self.used.values().filter(|u|!u.bad.is_empty()).count())?;for(label,usage)in &self.used{(self.poll)().map_err(PolicyFailure::Operational)?;if usage.bad.is_empty(){continue}let message=if usage.bad.len()==1{text(self.work,format_args!("an override of {label} is missing keyword args"))?}else{text(self.work,format_args!("{} overrides of {label} are missing keyword args",usage.bad.len()))?};let note_count=usage.bad.len().checked_add(usage.called_at.len()).ok_or_else(oom)?;let mut notes=vector(self.work,note_count)?;
  for(owner,bad)in &usage.bad{struct Missing<'a>(&'a [&'a str]);impl fmt::Display for Missing<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{for(i,name)in self.0.iter().enumerate(){if i>0{f.write_str("\", \"")?}f.write_str(name)?}Ok(())}}notes.push(Note{point:bad.at,message:text(self.work,format_args!("{owner} is missing \"{}\"",Missing(&bad.missing)))?});}
  for(name,call)in &usage.called_at{if !usage.bad.values().any(|bad|bad.missing.iter().any(|m|m==name)){continue}let message=if call.others>0{text(self.work,format_args!("called with {name:?} here, and {} other places",call.others))?}else{text(self.work,format_args!("called with {name:?} here"))?};notes.push(Note{point:Point::Source(call.at),message});}rows.push(Finding{point:usage.definition,message,notes});}Ok(rows)}
}
impl<W:EffectReportWork> crate::checker_expression_visit::KeywordObserver<PolicyFailure> for Fold<'_, '_,W>{fn begin_call(&mut self,tree:&SemanticTree,fact:&CallableFact,name:&str)->Result<(),PolicyFailure>{(self.poll)().map_err(PolicyFailure::Operational)?;if !std::ptr::eq(tree,self.archive.tree()){return Err("keyword call tree differs from fold owner".into())}crate::checker_call_facts::require_original_group_chronology_using(tree,self.profile,fact,name,&mut||(self.poll)().map_err(PolicyFailure::Operational))?;Ok(())}fn accepted_argument(&mut self,tree:&SemanticTree,fact:&CallableFact,receiver:SymbolId,name:&str,key:&Expr,at:Span)->Result<(),PolicyFailure>{
 if !std::ptr::eq(tree,self.archive.tree()){return Err("keyword call tree differs from fold owner".into())}if let Some(usage)=accepted_use(self.archive,self.profile,fact,receiver,name,key,at,self.poll)?{self.record_use(usage)?;}Ok(())
}}
/// Atomic whole-archive fold. The consumer cannot take ownership of its funded
/// arrays; all fold/output buffers physically drop before the caller's work.
pub fn with_archived<W:EffectReportWork>(archive:&BodyArchive,resolver:&(impl Resolver+?Sized),profile:PackedU128,admission:&ExecutionAdmission,work:&mut W,checkpoint:&dyn Fn()->io::Result<()>,consume:impl FnOnce(&Findings<'_>)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{
 checkpoint().map_err(PolicyFailure::Operational)?;if resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("keyword resolver belongs to another archive".into())}archive.tree().validate_checker_builtin_profile(profile).map_err(|e|format!("keyword profile: {e:?}"))?;
 let order=crate::checker_order::ArchivedOrder::build(archive,admission,&mut||checkpoint(),&mut|n|work.reserve(n))?;
 let mut fold=Fold{archive,profile,work,poll:checkpoint,used:BTreeMap::new(),names:BTreeSet::new()};
 let pending=(||{for rank in 0..order.len(){checkpoint().map_err(PolicyFailure::Operational)?;let ordinal=order.ordinal(rank).ok_or("keyword original body order absent")?;let body=archive.parse_checked(ordinal).map_err(|e|match e{dm_tree::frontend::BodySyntaxFailure::Operational(actual)=>PolicyFailure::Operational(actual),dm_tree::frontend::BodySyntaxFailure::Syntax(e)=>e.message.into()})?;crate::checker_expression_visit::keyword_calls_archived(archive,&body,resolver,profile,checkpoint,&mut fold)?;}
 complete_original_overrides(&mut fold,&order,resolver,checkpoint)?;
 let findings=Findings{archive,rows:fold.finish()?};checkpoint().map_err(PolicyFailure::Operational)?;consume(&findings)?;checkpoint().map_err(PolicyFailure::Operational)?;Ok(())})();
 if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;pending
}

#[cfg(test)]mod tests{use super::*;#[test]fn keyword_lexical_group_order_is_original_concatenated_key_order_not_owner_tuple_order(){let mut keys=[Group{owner:"/datum/base",name:"z"},Group{owner:"/datum/base/child",name:"a"},Group{owner:"(global)",name:"a"}];keys.sort();assert_eq!(keys.map(|key|key.to_string()),["(global)/proc/a","/datum/base/child/proc/a","/datum/base/proc/z"]);}}

fn accepted_use(archive:&BodyArchive,profile:PackedU128,fact:&CallableFact,receiver:SymbolId,name:&str,key:&Expr,at:Span,poll:&dyn Fn()->io::Result<()>)->Result<Option<crate::checker_effects::AcceptedKeywordUse>,PolicyFailure>{
 poll().map_err(PolicyFailure::Operational)?;let tree=archive.tree();let target=crate::checker_effects::callable_target(tree,profile,fact)?;let builtin=matches!(target,EffectTarget::Builtin(_));let signature=fact.metadata().and_then(|m|m.procedure.as_ref()).ok_or("keyword resolved signature absent")?;let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("keyword actual spelling catalog: {e:?}"))?;if catalog.profile!=profile{return Err("keyword profile differs".into())}let spelling=|id|if builtin{catalog.spelling(id)}else{tree.symbols().text(id)}.ok_or("keyword actual spelling absent");let mut accepted=None;for parameter in signature.signature.parameters.iter(){poll().map_err(PolicyFailure::Operational)?;if key_matches(key,spelling(parameter.name)?)?{accepted=Some(parameter.name);break}}let Some(accepted)=accepted else{return Ok(None)};let actual_name=match fact{CallableFact::Source{identity,..}=>identity.name,CallableFact::CheckerBuiltin{name,..}=>*name,CallableFact::Missing=>return Err("keyword actual callable is missing".into())};if actual_name!=SymbolId::of(name)||spelling(actual_name)?!=name{return Err("keyword actual callable spelling differs".into())}tree.symbols().text(receiver).ok_or("keyword static receiver spelling absent")?;Ok(Some(crate::checker_effects::AcceptedKeywordUse{target,receiver,name:actual_name,accepted,at}))
}
impl<'a,W:EffectReportWork> Fold<'a,'_,W>{fn record_use(&mut self,usage:crate::checker_effects::AcceptedKeywordUse)->Result<(),PolicyFailure>{let builtin=matches!(usage.target,EffectTarget::Builtin(_));let original_name=self.spelling(usage.name,builtin)?;let accepted=self.spelling(usage.accepted,builtin)?;let owner=self.archive.tree().symbols().text(usage.receiver).ok_or("keyword static receiver spelling absent")?;let group=Group{owner:if owner=="/"{"(global)"}else{owner},name:original_name};let at=usage.at;

 if !self.names.contains(original_name){map_entry::<&str,_>(self.work)?;self.names.insert(original_name);}
 if !self.used.contains_key(&group){map_entry::<(Group<'_>,Usage<'_>),_>(self.work)?;let definition=self.point(usage.target)?;self.used.insert(group,Usage{definition,called_at:BTreeMap::new(),bad:BTreeMap::new()});}
 let usage=self.used.get_mut(&group).ok_or("keyword inserted usage absent")?;if let Some(call)=usage.called_at.get_mut(accepted){call.others=call.others.checked_add(1).ok_or("keyword call count overflow")?;}else{map_entry::<(&str,CalledAt),_>(self.work)?;usage.called_at.insert(accepted,CalledAt{at,others:0});}Ok(())
}}

/// Per-BODY scalar uses from the actual same evaluator. No expression/source
/// owner is retained; the existing whole-archive fold consumes them later.
pub(crate) struct Recorder<'a>{pub archive:&'a BodyArchive,pub profile:PackedU128,pub budget:&'a crate::checker_effects::output::ReportBudget,pub poll:&'a dyn Fn()->io::Result<()>,pub rows:&'a mut Vec<crate::checker_effects::AcceptedKeywordUse>}
impl crate::checker_expression_visit::KeywordObserver<PolicyFailure> for Recorder<'_>{fn begin_call(&mut self,tree:&SemanticTree,fact:&CallableFact,name:&str)->Result<(),PolicyFailure>{(self.poll)().map_err(PolicyFailure::Operational)?;if !std::ptr::eq(tree,self.archive.tree()){return Err("recorded keyword call belongs to another archive".into())}crate::checker_call_facts::require_original_group_chronology_using(tree,self.profile,fact,name,&mut||(self.poll)().map_err(PolicyFailure::Operational))?;Ok(())}fn accepted_argument(&mut self,tree:&SemanticTree,fact:&CallableFact,receiver:SymbolId,name:&str,key:&Expr,at:Span)->Result<(),PolicyFailure>{if !std::ptr::eq(tree,self.archive.tree()){return Err("recorded keyword call belongs to another archive".into())}if let Some(usage)=accepted_use(self.archive,self.profile,fact,receiver,name,key,at,self.poll)?{self.budget.push(self.rows,usage).map_err(|message|PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;}Ok(())}}

fn complete_original_overrides<W:EffectReportWork>(fold:&mut Fold<'_,'_,W>,order:&crate::checker_order::ArchivedOrder<'_>,resolver:&(impl Resolver+?Sized),checkpoint:&dyn Fn()->io::Result<()>)->Result<(),PolicyFailure>{let archive=fold.archive;
 // Bodyless fixed builtin procedures participate in original check_kwargs too.
 // Their immutable catalog is borrowed directly; no projected roster is built.
 // Each original group orders source formals, its pre-registered builtin,
 // then implicit source values. ArchivedOrder already normalizes source values.
 for formal in [true,false]{
  if !formal{let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("keyword original builtin final phase: {e:?}"))?;for row in catalog.declarations.iter().filter(|row|matches!(row.kind,MemberKind::Proc|MemberKind::Verb)){checkpoint().map_err(PolicyFailure::Operational)?;fold.check_builtin(row,resolver)?;}}
  for rank in 0..order.len(){checkpoint().map_err(PolicyFailure::Operational)?;let ordinal=order.ordinal(rank).ok_or("keyword original override order absent")?;let id=archive.callables().identity(ordinal).ok_or("keyword original override identity absent")?;let member=archive.callables().members().get(ordinal).and_then(|id|archive.tree().member(*id)).ok_or("keyword original phase member absent")?;if (member.definition==dm_tree::DefinitionMode::Declare)==formal{fold.check_override(id,resolver)?;}}
 }
Ok(())}

/// Whole kwargs judge over the same sealed BODY uses. No AST/call evaluation.
/// Caller supplies only existing BODY outcomes, authenticated before any use.
pub fn with_cached_body_uses<W:EffectReportWork>(input:&Arc<crate::checker_effects::EffectInput>,resolver:&(impl Resolver+?Sized),admission:&ExecutionAdmission,work:&mut W,checkpoint:&dyn Fn()->io::Result<()>,mut obtain:impl FnMut(usize,&mut dyn FnMut(&crate::checker_effects::BodyEffects)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>,consume:impl FnOnce(&Findings<'_>)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{
 checkpoint().map_err(PolicyFailure::Operational)?;input.require_original_checker_source()?;let archive=input.archive().as_ref();let profile=input.profile();if resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("cached keyword resolver belongs to another archive".into())}
 let order=crate::checker_order::ArchivedOrder::build(archive,admission,&mut||checkpoint(),&mut|bytes|work.reserve(bytes))?;let mut fold=Fold{archive,profile,work,poll:checkpoint,used:BTreeMap::new(),names:BTreeSet::new()};
 let pending=(||{for rank in 0..order.len(){checkpoint().map_err(PolicyFailure::Operational)?;let ordinal=order.ordinal(rank).ok_or("cached keyword original order absent")?;let mut delivered=false;obtain(ordinal,&mut|body|{if delivered{return Err("cached keyword body was not delivered exactly once at admitted ordinal".into())}delivered=true;body.with_original_keyword_uses(input,ordinal,|uses|{for usage in uses{checkpoint().map_err(PolicyFailure::Operational)?;fold.record_use(*usage)?;}Ok::<(),PolicyFailure>(())})??;Ok(())})?;if !delivered{return Err("cached keyword body contribution missing".into())}}
 complete_original_overrides(&mut fold,&order,resolver,checkpoint)?;let findings=Findings{archive,rows:fold.finish()?};checkpoint().map_err(PolicyFailure::Operational)?;consume(&findings)?;checkpoint().map_err(PolicyFailure::Operational)?;Ok(())})();if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;pending
}
